import { describe, expect, it } from 'vitest';

import { AccountInformation } from '../../src/format/account';
import { DatabaseOptions } from '../../src/format/options';
import { FlatPackReader } from '../../src/format/reader';
import { Revision } from '../../src/format/revision';
import { FlatPackWriter } from '../../src/format/writer';

describe('AccountInformation', () => {
  it('round-trips all five fields in order', () => {
    const account = new AccountInformation('name', 'user', 'pass', 'https://x', 'note');
    const writer = new FlatPackWriter();
    account.flatPack(writer);
    const reader = new FlatPackReader(writer.toBytes());
    expect(AccountInformation.assemble(reader)).toMatchObject({
      accountName: 'name',
      userId: 'user',
      password: 'pass',
      url: 'https://x',
      notes: 'note',
    });
    expect(reader.atEof()).toBe(true);
  });

  it('defaults every field to the empty string', () => {
    expect(new AccountInformation()).toMatchObject({
      accountName: '',
      userId: '',
      password: '',
      url: '',
      notes: '',
    });
  });

  it('equals() compares all five fields', () => {
    const account = new AccountInformation('n', 'u', 'p', 'url', 'note');
    expect(account.equals(new AccountInformation('n', 'u', 'p', 'url', 'note'))).toBe(true);
    expect(account.equals(new AccountInformation('n', 'u', 'p', 'url', 'other'))).toBe(false);
  });
});

describe('DatabaseOptions', () => {
  it('normalises null/undefined to the empty string', () => {
    const options = new DatabaseOptions();
    options.remoteLocation = null;
    options.authDBEntry = undefined;
    expect(options.remoteLocation).toBe('');
    expect(options.authDBEntry).toBe('');
  });

  it('round-trips both fields', () => {
    const options = new DatabaseOptions('https://remote/upm.db', 'auth');
    const writer = new FlatPackWriter();
    options.flatPack(writer);
    const back = DatabaseOptions.assemble(new FlatPackReader(writer.toBytes()));
    expect(back.remoteLocation).toBe('https://remote/upm.db');
    expect(back.authDBEntry).toBe('auth');
  });
});

describe('Revision', () => {
  it('starts at 0 and increments', () => {
    const revision = new Revision();
    expect(revision.get()).toBe(0);
    expect(revision.increment()).toBe(1);
    expect(revision.get()).toBe(1);
  });

  it('round-trips through flat-pack', () => {
    const revision = new Revision(42);
    const writer = new FlatPackWriter();
    revision.flatPack(writer);
    expect(Revision.assemble(new FlatPackReader(writer.toBytes())).get()).toBe(42);
  });
});
